{
  "missionStatement": "Conduct comprehensive online research on room-temperature superconductivity and update the repository's documents with the latest findings, proposed chemistry and physics, and actionable strategies for discovery and manufacturing.",
  "criteria": [
    {
      "description": "Literature review document is updated with at least 5 new references from 2020+ on room-temperature superconductivity, including hydride and nickelate systems.",
      "expectedFiles": ["literature_review.md"]
    },
    {
      "description": "Theoretical framework document includes a section on the latest theories (e.g., BCS-like, excitonic, or topological) applied to new materials.",
      "expectedFiles": ["theoretical_framework.md"]
    },
    {
      "description": "Candidate materials list is expanded with at least 3 new compounds (e.g., H3S, LaH10, YNi2B2C) and their predicted Tc and synthesis conditions.",
      "expectedFiles": ["candidate_materials.md", "data/superconductor_database.json"]
    },
    {
      "description": "Synthesis methods document includes detailed protocols for high-pressure synthesis of hydride superconductors and thin-film deposition of nickelates.",
      "expectedFiles": ["synthesis_methods.md"]
    },
    {
      "description": "Characterization techniques document includes a section on measuring Tc under high pressure and using muon spin rotation.",
      "expectedFiles": ["characterization_techniques.md"]
    },
    {
      "description": "Proposed chemistry and physics document is rewritten with a coherent strategy for discovering room-temperature superconductors, including specific compound families and doping approaches.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Roadmap document is updated with milestones for experimental validation of proposed compounds, including timeline and resource requirements.",
      "expectedFiles": ["roadmap.md"]
    },
    {
      "description": "Online research summary document is updated with key findings from web searches, including URLs and data points.",
      "expectedFiles": ["docs/online_research_summary.md"]
    },
    {
      "description": "All existing unit tests in tests/ pass without errors.",
      "expectedFiles": []
    },
    {
      "description": "Superconductor database JSON is updated with new entries for at least 3 compounds, including Tc, structure, and reference.",
      "expectedFiles": ["data/superconductor_database.json"]
    }
  ]
}

{
  "missionStatement": "Integrate online research on room-temperature superconductivity to produce an updated, comprehensive proposal for the chemistry and physics of discovering and manufacturing room-temperature superconducting compounds, reflected in the key project documents.",
  "criteria": [
    {
      "description": "Conduct online research on recent advances (2020-2025) in room-temperature superconductivity and document findings in docs/online_research_summary.md.",
      "expectedFiles": ["docs/online_research_summary.md"]
    },
    {
      "description": "Update literature_review.md to include at least 5 new peer-reviewed references from the online research.",
      "expectedFiles": ["literature_review.md"]
    },
    {
      "description": "Update theoretical_framework.md to incorporate at least two new theoretical models (e.g., hydride superconductivity, topological superconductivity) supported by the research.",
      "expectedFiles": ["theoretical_framework.md"]
    },
    {
      "description": "Update candidate_materials.md to add at least 3 new candidate compounds or doping strategies identified from the research.",
      "expectedFiles": ["candidate_materials.md"]
    },
    {
      "description": "Update synthesis_methods.md to describe at least two new synthesis techniques (e.g., high-pressure synthesis, chemical vapor deposition) relevant to the new candidates.",
      "expectedFiles": ["synthesis_methods.md"]
    },
    {
      "description": "Update characterization_techniques.md to include at least two advanced characterization methods (e.g., muon spin rotation, neutron scattering) for verifying superconductivity.",
      "expectedFiles": ["characterization_techniques.md"]
    },
    {
      "description": "Update proposed_chemistry_physics.md to present a coherent, research-backed proposal for discovering and manufacturing room-temperature superconducting compounds, integrating findings from all updated documents.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Update roadmap.md to reflect new milestones and timelines based on the updated research and proposal.",
      "expectedFiles": ["roadmap.md"]
    },
    {
      "description": "Run the existing test suite (pytest tests/) and ensure all tests pass after any document or script changes.",
      "expectedFiles": []
    },
    {
      "description": "Update data/superconductor_database.json with new material properties from the updated candidate materials list.",
      "expectedFiles": ["data/superconductor_database.json"]
    }
  ]
}

